+//! Bounded cumulative accounting, separate from global admission gauges.
+use std::{
+    cell::Cell,
+    sync::atomic::{AtomicU64, AtomicUsize, Ordering},
+};
+
+const LANES: usize = 32;
+static NEXT_LANE: AtomicUsize = AtomicUsize::new(0);
+
+thread_local! {
+    // A non-dropping, constant TLS slot needs no allocation or registration.
+    static LANE: Cell<usize> = const { Cell::new(usize::MAX) };
+}
+
+#[repr(align(64))]
+struct Lane(AtomicU64);
+
+/// A cumulative counter with bounded storage and no per-update allocation.
+///
+/// Each thread reuses one of 32 cache-separated lanes across all counters.
+/// Reusing a lane remains atomic; more threads only increase contention. Retired
+/// threads leave their cumulative contribution in place. `load` sums atomic
+/// lane reads and is exact at quiescence, rather than a point-in-time snapshot
+/// across writers. Addition and summation wrap modulo 2^64 like `AtomicU64`.
+/// Resource limits and reservations must continue to use global atomics.
+pub struct Counter {
+    lanes: [Lane; LANES],
+}
+
+impl Default for Counter {
+    fn default() -> Self {
+        Self {
+            lanes: std::array::from_fn(|_| Lane(AtomicU64::new(0))),
+        }
+    }
+}
+
+impl Counter {
+    /// Record completed work; this does not reserve a resource or return a
+    /// globally ordered previous value.
+    pub fn add(&self, amount: u64) {
+        LANE.with(|slot| {
+            let mut lane = slot.get();
+            if lane == usize::MAX {
+                lane = NEXT_LANE.fetch_add(1, Ordering::Relaxed) % LANES;
+                slot.set(lane);
+            }
+            self.lanes[lane].0.fetch_add(amount, Ordering::Relaxed);
+        });
+    }
+
+    /// Read the cumulative total. Ordering applies to each atomic lane read;
+    /// the counter does not synchronize publication of application data.
+    pub fn load(&self, ordering: Ordering) -> u64 {
+        self.lanes
+            .iter()
+            .fold(0u64, |sum, lane| sum.wrapping_add(lane.0.load(ordering)))
+    }
+}
+
+#[cfg(test)]
+mod tests {
+    use super::*;
+    use std::sync::{Arc, Barrier};
+
+    #[test]
+    fn concurrent_writers_reuse_lanes_and_retired_totals_survive() {
+        let counter = Arc::new(Counter::default());
+        let start = Arc::new(Barrier::new(65));
+        let writers: Vec<_> = (1..=64)
+            .map(|value| {
+                let (counter, start) = (counter.clone(), start.clone());
+                std::thread::spawn(move || {
+                    start.wait();
+                    for _ in 0..1000 {
+                        counter.add(value);
+                    }
+                })
+            })
+            .collect();
+        start.wait();
+        for writer in writers {
+            writer.join().unwrap();
+        }
+        assert_eq!(counter.load(Ordering::Relaxed), 64 * 65 / 2 * 1000);
+        counter.add(7);
+        assert_eq!(counter.load(Ordering::Relaxed), 64 * 65 / 2 * 1000 + 7);
+    }
+
+    #[test]
+    fn totals_wrap_across_lanes_and_updates() {
+        let counter = Counter::default();
+        counter.lanes[0].0.store(u64::MAX, Ordering::Relaxed);
+        counter.lanes[1].0.store(2, Ordering::Relaxed);
+        assert_eq!(counter.load(Ordering::Relaxed), 1);
+        counter.add(u64::MAX);
+        assert_eq!(counter.load(Ordering::Relaxed), 0);
+    }
+}

